style.css:
@-moz-document domain("open.spotify.com") {
/* --- MIDNIGHT MINIMAL THEME FOR SPOTIFY --- */
    
    :root {
        --background-base: #030305 !important;
        --background-highlight: #0a0a0f !important;
        --background-press: #12121a !important;
        --background-elevated-base: #07070a !important;
        --background-elevated-highlight: #0d0d14 !important;
        
        --text-base: #f0f0f5 !important;
        --text-subdued: #757585 !important;
        --text-brightaccent: #00f2fe !important; /* Midnight Neon Accent */
        
        --essential-base: #f0f0f5 !important;
        --essential-subdued: #454555 !important;
        
        /* Smooth transitions for a premium minimalist feel */
        --fallback-fonts: 'Helvetica Neue', Helvetica, Arial, sans-serif;
    }

    /* Core Application Backgrounds */
    body, 
    .Root__main-view, 
    .main-view-container,
    .Root__top-bar,
    footer,
    [id="main"] {
        background-color: var(--background-base) !important;
    }

    /* Minimalist Sidebar Layout */
    .Root__nav-bar {
        background-color: #000000 !important;
        border-right: 1px solid #09090f !important;
    }
    
    /* Hide aggressive grid borders and dividers */
    .Root__main-view,
    .main-rootlist-rootlistDivider,
    hr {
        border: none !important;
        background: transparent !important;
    }

    /* Customizing Cards (Playlists, Albums) */
    .main-card-card {
        background: var(--background-elevated-base) !important;
        transition: background 0.3s ease, transform 0.2s ease !important;
        border-radius: 6px !important;
        border: 1px solid #08080c !important;
    }

    .main-card-card:hover {
        background: var(--background-elevated-highlight) !important;
        border-color: #12121f !important;
    }

    /* Minimalist Progress & Volume Bars */
    .playback-bar, .volume-bar {
        --bg-color: #181824 !important;
        --fg-color: var(--text-brightaccent) !important;
    }
    
    .progress-bar {
        --progress-bar-transform: 0px;
        --progress-bar-bg-color: #1a1a26 !important;
        --progress-bar-fg-color: var(--text-brightaccent) !important;
    }

    /* Top Navigation Profile Bar */
    .main-entityHeader-headerText, 
    .main-topBar-container,
    .main-topBar-background {
        background-color: transparent !important;
        background: transparent !important;
    }

    /* Clean Track Rows */
    .main-trackList-trackListRow {
        border-radius: 4px !important;
        transition: background-color 0.2s ease !important;
    }

    .main-trackList-trackListRow:hover {
        background-color: var(--background-highlight) !important;
    }

    .main-trackList-trackListRow--active .main-trackList-rowTitle {
        color: var(--text-brightaccent) !important;
    }

    /* Clean Up Play Buttons & UI Accents */
    .main-playButton-PlayButton,
    button[data-testid="play-button"],
    .main-playPauseButton-mainPlayPauseButton {
        --background-base: var(--text-brightaccent) !important;
        --background-highlight: #00d2dc !important;
        color: #030305 !important;
    }

    /* Hide Unnecessary Web Player Clutter */
    .main-topBar-UpgradeButton, 
    button[aria-label="Upgrade to Premium"],
    .main-genericButton-buttonSecondary {
        display: none !important;
    }
}
